const ShadcnStyles = "/* Opt in by loading AFTER ui.css. Complete CSS colour values (modern shadcn). */\n:root, :root[data-theme], :root:not([data-theme=\"light\"]):not(.light), .dark{\n  --ui-bg:var(--background);\n  --ui-fg:var(--foreground);\n  --ui-subtle:var(--muted);\n  --ui-muted:var(--muted-foreground);\n  --ui-border:var(--border);\n  --ui-ring:var(--ring);\n  --ui-primary:var(--primary);\n  --ui-primary-fg:var(--primary-foreground);\n  --ui-danger:var(--destructive);\n  --ui-danger-fg:var(--destructive-foreground);\n  --ui-success:var(--success, var(--primary));\n  --ui-success-fg:var(--success-foreground, var(--primary-foreground));\n  --ui-warning:var(--warning, var(--primary));\n  --ui-warning-fg:var(--warning-foreground, var(--primary-foreground));\n  --ui-info:var(--info, var(--primary));\n  --ui-info-fg:var(--info-foreground, var(--primary-foreground));\n  --ui-image-bg:var(--muted);\n  --ui-radius:var(--radius);\n  --ui-info-bg:color-mix(in srgb,var(--ui-info) 10%,var(--ui-bg));\n  --ui-success-bg:color-mix(in srgb,var(--ui-success) 10%,var(--ui-bg));\n  --ui-warning-bg:color-mix(in srgb,var(--ui-warning) 10%,var(--ui-bg));\n  --ui-danger-bg:color-mix(in srgb,var(--ui-danger) 10%,var(--ui-bg));\n  --ui-overlay:color-mix(in srgb,var(--foreground) 45%,transparent);\n}\n\n/* Older shadcn: html data-ui-shadcn=\"hsl\" opts into HSL channel tokens. */\n:root[data-ui-shadcn=\"hsl\"], :root[data-ui-shadcn=\"hsl\"][data-theme], :root[data-ui-shadcn=\"hsl\"]:not([data-theme=\"light\"]):not(.light), [data-ui-shadcn=\"hsl\"] .dark{\n  --ui-bg:hsl(var(--background));\n  --ui-fg:hsl(var(--foreground));\n  --ui-subtle:hsl(var(--muted));\n  --ui-muted:hsl(var(--muted-foreground));\n  --ui-border:hsl(var(--border));\n  --ui-ring:hsl(var(--ring));\n  --ui-primary:hsl(var(--primary));\n  --ui-primary-fg:hsl(var(--primary-foreground));\n  --ui-danger:hsl(var(--destructive));\n  --ui-danger-fg:hsl(var(--destructive-foreground));\n  --ui-success:hsl(var(--success, var(--primary)));\n  --ui-success-fg:hsl(var(--success-foreground, var(--primary-foreground)));\n  --ui-warning:hsl(var(--warning, var(--primary)));\n  --ui-warning-fg:hsl(var(--warning-foreground, var(--primary-foreground)));\n  --ui-info:hsl(var(--info, var(--primary)));\n  --ui-info-fg:hsl(var(--info-foreground, var(--primary-foreground)));\n  --ui-image-bg:hsl(var(--muted));\n  --ui-overlay:color-mix(in srgb,hsl(var(--foreground)) 45%,transparent);\n}\n"
